.markdown-reading-view .markdown-preview-view table {
    width: auto !important;
    min-width: auto !important;
    max-width: none !important;
    table-layout: auto !important;
    border-collapse: collapse !important;
    margin: 0.5em 0 !important;
}

.markdown-reading-view .markdown-preview-view td,
.markdown-reading-view .markdown-preview-view th {
    min-width: 50px !important;
    width: auto !important;
    max-width: none !important;
    padding: 5px 5px !important;
    border: 1px solid var(--background-modifier-border) !important;
    white-space: nowrap !important;
    overflow: visible !important;
    text-overflow: clip !important;
    vertical-align: top !important;
    text-align: left !important;
}

.markdown-reading-view .markdown-preview-view th {
    font-weight: bold !important;
}

.markdown-reading-view .markdown-preview-view > div {
    overflow-x: auto !important;
    overflow-y: visible !important;
}

.markdown-source-view .cm-table-widget table,
.cm-embed-block.cm-table-widget table {
    width: max-content !important;
    min-width: min(1100px, 100%) !important;
    max-width: 100% !important;
    table-layout: auto !important;
    border-collapse: collapse !important;
    border-spacing: 0 !important;
    font-size: inherit !important;
    font-family: inherit !important;
    line-height: inherit !important;
}

.markdown-source-view .cm-table-widget,
.cm-embed-block.cm-table-widget {
    position: relative !important;
    display: inline-block !important;
}

.markdown-source-view .cm-table-widget th,
.cm-embed-block.cm-table-widget th {
    font-weight: bold !important;
}

.markdown-source-view .cm-table-widget .table-column-resize-handle,
.cm-embed-block.cm-table-widget .table-column-resize-handle,
.markdown-source-view .cm-table-widget .table-row-controls,
.cm-embed-block.cm-table-widget .table-row-controls,
.markdown-source-view .cm-table-widget .table-column-controls,
.cm-embed-block.cm-table-widget .table-column-controls {
    position: absolute !important;
    z-index: 100 !important;
    display: block !important;
    opacity: 1 !important;
    visibility: visible !important;
    pointer-events: auto !important;
}

.markdown-source-view .cm-table-widget .selected-row,
.cm-embed-block.cm-table-widget .selected-row,
.markdown-source-view .cm-table-widget .selected-column,
.cm-embed-block.cm-table-widget .selected-column {
    background-color: rgba(var(--interactive-accent-rgb), 0.1) !important;
}

/* Hide scrollbar for Obsidian mobile */
.view-content ::-webkit-scrollbar {
    display: none;
}

/* Ensure scrolling still works */
.view-content {
    -webkit-overflow-scrolling: touch;
}
